// Writes prompt.md, the convert flow's system prompt: rules, the cheat sheet from
// .smithers/instructions/app.md, and the separate examples/ pairs. Generated, never hand-edited.
//   node .smithers/flows/convert/build-prompt.mjs           write prompt.md
//   node .smithers/flows/convert/build-prompt.mjs --check   exit 1 if prompt.md is stale
import { readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import { casesIn } from "./cases.mjs"

const here = fileURLToPath(new URL(".", import.meta.url))
const root = join(here, "../../..")

export function cheatSheet(app = readFileSync(join(root, ".smithers/instructions/app.md"), "utf8")) {
  const start = app.indexOf("## Syntax cheat sheet")
  const end = app.indexOf("\n## ", start + 1)
  if (start < 0 || end < 0) throw new Error("app.md has no \"## Syntax cheat sheet\" section")
  return app.slice(start, end).trim()
}

export function exampleCases(dir = join(here, "examples")) {
  return casesIn(dir)
}

export function buildPrompt() {
  const examples = exampleCases().map((c) => `### ${c.name}\n\nInput:\n\n\`\`\`ts\n${c.input}\n\`\`\`\n\nOutput:\n\n\`\`\`ts\n${c.expected}\n\`\`\``)
  return `<!-- Generated by build-prompt.mjs from instructions/app.md and examples/. Do not edit. -->
# Convert Effect TypeScript to VibeLang

You convert one Effect 4 TypeScript file into the equivalent VibeLang file.

Answer with exactly one fenced \`ts\` code block holding the whole VibeLang file, and nothing else.

- Keep every export, with its name.
- Drop imports from \`"effect"\`: VibeLang has Effect's root modules and common functions in scope.
- Use the VibeLang forms below wherever the input uses the Effect form they replace.
- Keep the program's behavior. Add nothing the input does not do, and do not explain.

${cheatSheet().replace(/^## /m, "## ")}

## Examples

${examples.join("\n\n")}
`
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const target = join(here, "prompt.md")
  const next = buildPrompt()
  if (process.argv.includes("--check")) {
    const current = (() => { try { return readFileSync(target, "utf8") } catch { return "" } })()
    if (current !== next) { console.error("prompt.md is stale: run node .smithers/flows/convert/build-prompt.mjs"); process.exit(1) }
    console.log("prompt.md is up to date")
  } else {
    writeFileSync(target, next)
    console.log(`wrote prompt.md (${Buffer.byteLength(next)} bytes, ${exampleCases().length} examples)`)
  }
}

// Compiles every golden and example expected output with the converter's compile worker
// and pinned project, so neither set can hold an answer that does not compile.
//   node .smithers/flows/convert/score.mjs            compile in-process (needs the worker's project installed)
//   node .smithers/flows/convert/score.mjs --worker http://host:8080   use a running worker
// Exit 1 when any expected output fails. The model's outputs are scored the same way once the
// Smithers convert flow exists (see README.md).
import { fileURLToPath } from "node:url"
import { casesIn } from "./cases.mjs"
import { heldoutProblems } from "./check-heldout.mjs"

const problems = heldoutProblems()
if (problems.length) {
  console.error(problems.join("\n"))
  process.exit(1)
}
const suites = ["golden", "examples"].map((name) => ({ name, cases: casesIn(fileURLToPath(new URL(`./${name}/`, import.meta.url))) }))

const at = process.argv.indexOf("--worker")
const worker = at > 0 ? process.argv[at + 1] : undefined

async function compileOne(source) {
  if (worker) {
    const response = await fetch(new URL("/compile", worker), { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ source }) })
    return response.json()
  }
  const { compile, settings } = await import("../../../packages/converter-worker/compile.mjs")
  return compile(source, settings())
}

let failed = 0
for (const suite of suites) {
  let passed = 0
  for (const c of suite.cases) {
    const result = await compileOne(c.expected)
    const ok = result.exitCode === 0 && !result.timedOut && !(result.diagnostics ?? []).some((d) => d.severity === "error")
    if (ok) passed++
    else failed++
    console.log(`${ok ? "compiled" : "FAILED  "} ${suite.name}/${c.name}${ok ? "" : ` ${JSON.stringify(result).slice(0, 1000)}`}`)
  }
  console.log(`${passed} of ${suite.cases.length} ${suite.name} expected outputs compile`)
}
process.exit(failed ? 1 : 0)

// Reject gate sources in training examples or the prompt, even under different file names.
import { readFileSync, realpathSync } from "node:fs"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import { casesIn } from "./cases.mjs"

const here = fileURLToPath(new URL(".", import.meta.url))

// Compare tokens, ignoring comments and spacing between them. Keep literal contents and
// token boundaries: "a b" differs from "ab", as do identifiers `a b` and `ab`.
// Template interpolations are code; template text, strings and regexes preserve comment markers.
export function normalizeSource(source) {
  const tokens = []
  let i = 0
  function quoted(quote) {
    const start = i++
    while (i < source.length) {
      const c = source[i++]
      if (c === "\\") i++
      else if (c === quote) break
    }
    tokens.push(source.slice(start, i))
  }
  function template() {
    tokens.push(source[i++])
    let start = i
    while (i < source.length) {
      if (source[i] === "\\") { i += 2; continue }
      if (source[i] === "`") {
        tokens.push("template:" + source.slice(start, i), source[i++])
        return
      }
      if (source.startsWith("${", i)) {
        tokens.push("template:" + source.slice(start, i), "${")
        i += 2
        code(true)
        start = i
      } else i++
    }
    tokens.push("template:" + source.slice(start, i))
  }
  function code(interpolation = false) {
    let braces = 0
    while (i < source.length) {
      const c = source[i]
      if (/\s/.test(c)) { i++; continue }
      if (source.startsWith("//", i)) {
        while (i < source.length && !/[\r\n]/.test(source[i])) i++
        continue
      }
      if (source.startsWith("/*", i)) {
        const end = source.indexOf("*/", i + 2)
        i = end < 0 ? source.length : end + 2
        continue
      }
      if (c === '"' || c === "'") { quoted(c); continue }
      if (c === "`") { template(); continue }
      if (c === "/" && (tokens.length === 0 || /^(?:[=([{,:;!?]|=>|return|throw|case|yield|\|\||&&|\?\?)$/.test(tokens.at(-1)))) {
        const start = i++
        let inClass = false
        while (i < source.length) {
          const r = source[i++]
          if (r === "\\") i++
          else if (r === "[") inClass = true
          else if (r === "]") inClass = false
          else if (r === "/" && !inClass) break
        }
        while (/[a-z]/i.test(source[i] ?? "")) i++
        tokens.push(source.slice(start, i))
        continue
      }
      const word = /^[\p{ID_Start}\p{ID_Continue}\d_$]+/u.exec(source.slice(i))
      const punctuation = /^(?:===|!==|>>>|\*\*=|&&=|\|\|=|\?\?=|=>|==|!=|<=|>=|\+\+|--|&&|\|\||\?\?|\?\.|\*\*|<<|>>|\+=|-=|\*=|\/=|%=|&=|\|=|\^=|\|>|\.\.\.)/.exec(source.slice(i))
      const token = word?.[0] ?? punctuation?.[0] ?? c
      tokens.push(token)
      i += token.length
      if (c === "{") braces++
      if (c === "}") {
        if (interpolation && braces === 0) return
        braces--
      }
    }
  }
  code()
  return tokens.length ? " " + tokens.map((token) => JSON.stringify(token)).join(" ") + " " : ""
}

function promptSources(prompt) {
  const sources = []
  const lines = prompt.split(/\r?\n/)
  for (let i = 0; i < lines.length; i++) {
    const fence = /^\s{0,3}(`{3,}|~{3,})/.exec(lines[i])
    if (!fence) continue
    const close = new RegExp(`^\\s{0,3}${fence[1][0]}{${fence[1].length},}\\s*$`)
    const body = []
    while (++i < lines.length && !close.test(lines[i])) body.push(lines[i])
    sources.push(body.join("\n"))
  }
  // Also catch an unfenced source pasted directly into prompt.md.
  sources.push(prompt)
  return sources
}

export function heldoutProblems({ golden = casesIn(join(here, "golden")), examples = casesIn(join(here, "examples")), prompt = readFileSync(join(here, "prompt.md"), "utf8") } = {}) {
  const candidates = examples.flatMap((entry) => [
    { location: `examples/${entry.name}/input.ts`, source: entry.input },
    { location: `examples/${entry.name}/expected.vibe`, source: entry.expected }
  ])
  candidates.push(...promptSources(prompt).map((source) => ({ location: "prompt.md", source })))
  const normalized = candidates.map((entry) => ({ ...entry, source: normalizeSource(entry.source) }))
  const problems = new Set()
  for (const entry of golden) {
    for (const [file, source] of [["input.ts", entry.input], ["expected.vibe", entry.expected]]) {
      const heldout = normalizeSource(source)
      if (!heldout) throw new Error(`golden/${entry.name}/${file} has no source tokens`)
      for (const candidate of normalized) {
        if (candidate.source.includes(heldout)) problems.add(`${candidate.location} overlaps held-out golden/${entry.name}/${file} (normalized source)`)
      }
    }
  }
  return [...problems]
}

// Compare real paths: on macOS tmpdir() is under /var, a symlink to /private/var, and
// import.meta.url names the resolved path while argv[1] keeps the one the caller passed.
if (process.argv[1] && fileURLToPath(import.meta.url) === realpathSync(process.argv[1])) {
  const problems = heldoutProblems()
  if (problems.length) {
    console.error(problems.join("\n"))
    process.exitCode = 1
  } else console.log("check-heldout: examples/ and prompt.md contain no golden source")
}

# Why VibeLang?

VibeLang uses Effect to make a program's expected failures and dependencies visible to the compiler. Choose it when application logic needs coordinated retries, cancellation, resource cleanup, and service substitution.

## Describe work before running it

```vibe
error InvalidQuantity {
  quantity: number
}

function unitPrice(total: number, quantity: number) {
  if (quantity <= 0) throw new InvalidQuantity({ quantity })
  return total / quantity
}
// number!InvalidQuantity!

const quote = () => unitPrice(72, 6)
```

`quote` holds a reusable program. Calling `quote()` inside another function runs it and returns the number. The error channel records the validation failure, so callers can handle it without inspecting this implementation.

## Share an application foundation

```vibe
service Prices {
  total(sku: string): number!InvalidQuantity
}

function receipt(sku: string) {
  const amount = Prices.total(sku)
  return `Total: ${amount}`
}
// string!InvalidQuantity!Prices

const PricesTest = Layer.succeed(Prices, {
  total(_sku) { return 18 }
})

function preview() {
  provide PricesTest { return receipt("pencil-box") }
}
```

Services carry dependencies through the same contract as errors and successes. Layers supply implementations and manage their resources. Tests can provide an in-memory implementation while the application provides a database or HTTP implementation.

## Apply composable production tools

```vibe
function resilientReceipt(sku: string) {
  return receipt(sku)
    |> retry(%, { times: 2 })
    |> timeout(%, "800 millis")
    |> withSpan(%, "receipt")
}
```

These operators share Effect's execution and cleanup rules. Retry repeats the program from the beginning; timeout interrupts work that exceeds its deadline; the span describes the whole operation. Choose retry only for failures worth repeating, and make repeated writes safe before retrying them.

Use the same foundation for streams, caches, validated input, configuration, and observability. You can introduce those modules as concrete problems arise.

## Learn with practical programs

Start with one operation that reads data, validates it, and returns a result. Test its success and failure cases, then add a service boundary and a deadline. Continue with [The Effect Type](003-the-effect-type.md) and [Creating Effects](005-creating-effects.md).

## Coming from Effect

VibeLang keeps Effect's library and runtime. Ordinary statements replace most sequencing operators, while retry, timeout, concurrency, and provisioning keep their library APIs with program arguments.

[Upstream Effect page](https://effect.website/docs/v4/getting-started/why-effect)

# Expected Errors

Expected errors describe situations callers can handle: invalid input, a denied operation, or an unavailable dependency. VibeLang infers them in the `E` channel and narrows them inside `catch`.

[Upstream page](https://effect.website/docs/v4/error-management/expected-errors)

## Constructing typed failures

```vibe
error InvalidCode {
  input: string
}
error ItemMissing {
  code: string
}

function normalizeCode(input: string) {
  const code = input.trim()
  if (code.length === 0) throw new InvalidCode({ input })
  return code.toUpperCase()
}
// string!InvalidCode!
```

`error InvalidCode { input: string }` declares an expected failure. The declaration is a class: its constructor takes the fields, every field is readonly, and each instance has a readonly `_tag` equal to the class name. `throw` adds the class to `E`. `error Timeout` declares an error without fields. The declaration is short for `class InvalidCode extends TaggedError("InvalidCode")<{ readonly input: string }> {}`, which also compiles; the global `TaggedError` is Effect's `Data.TaggedError`. `Effect.fail(error)` is also available, and `Effect.failSync(() => error)` defers construction until execution, though a function body already gives you that deferral.

Trusted built-ins can add expected failures too: `JSON.parse` adds `SyntaxError`. A plain TypeScript function needs the `try` hatch or a trusted declaration, `/** @vibelang trusted */`; each `@throws {T}` names an exported exception class that joins `E`, and unlisted exceptions are defects. Effect's own packages are trusted already, so calls such as `Option.isNone` need no boundary.

## Failing in an expression

```vibe
error MissingPort

function port(env: Map<string, string>) {
  return env.get("PORT") ?? throw new MissingPort()
}
// string!MissingPort!
```

`throw` also works in expression position, as the TC39 [throw expressions](https://github.com/tc39/proposal-throw-expressions) proposal writes it, and fails the same way the statement does. The right side of `??`, `||`, `&&`, and `?:` runs only when it is chosen.

## Tracking several error cases

```vibe
function findItem(input: string) {
  const code = normalizeCode(input)
  if (code !== "PEN") throw new ItemMissing({ code })
  return { code, label: "Fountain pen" }
}
// { code: string; label: string }!InvalidCode | ItemMissing!
```

A function collects the failures it throws and those its calls can produce. Sequential statements stop at the first failure, so no lookup happens after normalization fails. An explicit full contract checks this inferred union rather than replacing it.

## Turning failures into values

```vibe
function inspectItem(input: string) {
  const result = Effect.result(findItem(input))
  return result.match({
    onFailure: (error) => `unavailable: ${error._tag}`,
    onSuccess: (item) => item.label
  })
}

function optionalItem(input: string) {
  const item = Effect.option(findItem(input))
  return item.isNone() ? "No item" : item.value.label
}
```

`Effect.result` returns `Result<A, E>` in the success channel and removes the typed failure channel. `Effect.option` returns `Some` on success and discards a typed error as `None`. Use the latter only when every domain failure means absence. Causes without any expected failure still propagate; these Effect combinators can consume a mixed cause when it also contains an expected failure. Use ordinary catch when defects and interruption must always propagate intact.

## Recovering all failures

```vibe
function itemLabel(input: string) {
  try {
    return findItem(input).label
  } catch (error) {
    return `Unavailable (${error._tag})`
  }
}
// string!!
```

The catch receives `InvalidCode | ItemMissing` and handles both here. It handles only causes with no defect and no interruption. If several expected failures occur together, it receives the first and handles their whole cause.

```vibe
function itemLabelInline(input: string) {
  return findItem(input).label catch (error) => `Unavailable (${error._tag})`
}
// string!!
```

`catch` also works after an expression. `x catch (error) => handler` runs `x` and passes an expected failure to the handler, as `Effect.catch` does, with the same guard as the statement: defects and interruption pass through. `x catch fallback` evaluates the fallback instead, as `Effect.orElseSucceed` does; see [Fallback](016-fallback.md).

`Effect.catch(() => findItem(input), handler)` also recovers expected failures, but keeps Effect's own policy: it can recover a mixed cause containing an expected failure and drop the other reasons. `Effect.catchEager` uses that same policy and can apply recovery immediately when given an already computed `Exit`. Neither combinator has source catch's mixed-cause guard.

## Recovering selected failures

```vibe
function labelOrMissing(input: string) {
  try {
    return findItem(input).label
  } catch (error) {
    return match (error) {
      when ItemMissing: "Out of catalog";
      default: throw error;
    }
  }
}
// string!InvalidCode!

function labelByTag(input: string) {
  return Effect.catchTag(
    findItem(input),
    "ItemMissing",
    (error) => ({ code: error.code, label: "Out of catalog" })
  )
}
```

Catch the failure, then `match` on it: an arm such as `when ItemMissing:` handles that error class, and `default: throw error` passes the others on with their types, as `string!InvalidCode!` shows. The expression form takes the same `match`: `findItem(input).label catch (error) => match (error) { when ItemMissing: "Out of catalog"; default: throw error; }`. A `match` without `default` must handle every failure the `try` block can raise, or it is a compile error (EK4701), so a complete match needs no rethrow. `error is ItemMissing` tests one class in an `if`. `Effect.catchTag` removes the selected tagged case; it also accepts a nonempty array of tags sharing one handler. `Effect.catchTags` supplies a table of separate handlers.

```vibe
function withTagTable(input: string) {
  return Effect.catchTags(findItem(input), {
    InvalidCode: () => ({ code: "", label: "Enter a code" }),
    ItemMissing: (error) => ({ code: error.code, label: "Out of catalog" })
  })
}

function withFilter(input: string) {
  return Effect.catchFilter(
    () => findItem(input),
    Filter.tagged("ItemMissing"),
    (error) => ({ code: error.code, label: "Out of catalog" })
  )
}

function withPredicate(input: string) {
  return Effect.catchIf(
    () => findItem(input),
    (error) => error is ItemMissing,
    () => ({ code: "", label: "Out of catalog" })
  )
}
```

`catchIf` selects errors using a predicate or type guard. `catchFilter` accepts reusable selection logic from `Filter`; a narrowing filter removes the handled subtype. A boolean condition that handles only some values cannot promise that the whole subtype is gone.

## Filtering nested reasons

```vibe
error Busy { seconds: number }
error Rejected
error CatalogError {
  reason: Busy | Rejected
}

function remoteLabel(): string!CatalogError! {
  throw new CatalogError({ reason: new Busy({ seconds: 4 }) })
}

function explainBusy() {
  return Effect.catchReason(
    () => remoteLabel(), "CatalogError", "Busy",
    (reason) => `Try again in ${reason.seconds} seconds`
  )
}

function explainReasons() {
  return Effect.catchReasons(() => remoteLabel(), "CatalogError", {
    Busy: (reason) => `Wait ${reason.seconds} seconds`,
    Rejected: () => "Request rejected"
  })
}

function exposeReasons() {
  return Effect.unwrapReason(() => remoteLabel(), "CatalogError")
}
// string!Busy | Rejected!
```

These operators inspect the tagged error's readonly `reason` field. `catchReason` keeps the parent wrapper for unhandled reasons, while `catchReasons` selects several reasons at once. `unwrapReason` replaces the wrapper with its nested reason in `E` without recovering.

## Coming from Effect

Functions replace `Effect.gen`; calls run the callee. Pass a program such as `() => findItem(input)` when a recovery operator needs work it can control.

# Unexpected Errors

Defects report bugs and broken invariants outside the typed error contract. Keep domain recovery focused on expected errors, and inspect defects at a boundary that can report or isolate the failed operation.

[Upstream page](https://effect.website/docs/v4/error-management/unexpected-errors)

## Creating defects

```vibe
function decodeOpcode(opcode: number) {
  if (opcode !== 1) die(new Error("unknown internal opcode"))
  return "start"
}
// string!!
```

`Effect.die` terminates the computation with a defect. Prefer an `Error` with a useful message, so diagnostics include its stack. A JavaScript exception that no contract lists is also a defect; an explicit VibeLang `throw`, including `throw new Error(...)`, is a typed failure instead.

```vibe
function firstLabel(labels: ReadonlyArray<string>) {
  try {
    return Effect.fromOption(Option.fromNullishOr(labels[0]))
  } catch (error) {
    return "No label"
  }
}
```

`Option.getOrThrow` and `Schema.decodeUnknownSync` are trusted calls whose exceptions are defects, so ordinary catch does not see them. A catch whose try block has no expected failures gets warning EK2004 by default. Use a typed form such as `Effect.fromOption`, as above, or `Schema.decodeUnknownEffect` when callers need recovery. A JavaScript catch inside `Effect.gen` can see synchronous exceptions; a catch in `.vibe` follows the expected-failure contract instead.

## Promoting typed failures to defects

```vibe
error MissingSetting {
  name: string
}

function requireSetting(name: string) {
  throw new MissingSetting({ name })
}

function startup() {
  return Effect.orDie(requireSetting("region"))
}
// never!!

function startupWithMessage() {
  return requireSetting("region")
    |> Effect.mapError(%, (error) => new Error(`Startup needs ${error.name}`))
    |> Effect.orDie(%)
}
```

`orDie` removes `E` by moving typed failures into defect reasons. This changes what callers can recover from; use it where a failure violates a required invariant. Map the error before promotion when the defect needs a clearer message.

## Examining complete execution results

```vibe
function inspectStartup() {
  const outcome = Effect.exit(startup())
  if (outcome.isFailure()) {
    return outcome.cause.hasDies() ? "startup defect" : "startup stopped"
  }
  return "started"
}
```

`Effect.exit` returns `Exit<A, E>` as a successful value. A failure exit retains the full cause, including defects, interruption reasons, and combinations of reasons. This is broader than `Effect.result`, which exposes domain failures only; capturing an exit does not make an externally cancelled fiber immune to cancellation.

An `Exit` stays data when returned by a call. Constructing one with `Exit.succeed(value)` does not run it; calling a held exit runs that outcome.

## Recovering defects at a boundary

```vibe
function isolateDecoder(opcode: number) {
  return Effect.catchDefect(() => decodeOpcode(opcode), (defect) => {
    if (defect instanceof Error && defect.message === "unknown internal opcode") {
      log("Decoder disabled after an invariant failure")
      return "disabled"
    }
    return die(defect)
  })
}
```

`catchDefect` selects a defect and runs recovery; a cause with no defect propagates. On a mixed cause, recovery can consume the accompanying failures or interruption too, so use `catchCause` when every reason must inform that decision. Reraise defects you do not recognize. Ordinary `try`/`catch` does not intercept a defect, even if the defect value is an instance of a domain error class.

## Recovering a complete cause

```vibe
function decoderBoundary(opcode: number) {
  const outcome = exit(decodeOpcode(opcode))
  if (outcome is Exit.Success(let value)) return value
  const cause = outcome.cause
  if (cause.hasInterrupts()) throw cause
  if (cause.hasDies()) {
    log("Decoder failed", cause.reasons.map((reason) => reason._tag))
    return "disabled"
  }
  throw cause
}
```

`exit(program)` returns the whole outcome, as `Effect.exit` does, so a `Failure` exit's cause holds every reason: failures, defects, and interruption that ordinary catch clauses leave alone. Test it with `is` or `match` on `Exit.Success` and `Exit.Failure`. `throw cause` restores the original failure, every reason included, as `Effect.failCause` does, instead of turning the cause object into a typed error. Inspect every reason before recovering from a mixed cause, and preserve cancellation when the boundary has no reason to consume it.

export error EmptyName

export function greeting(name: string) {
  if (name.length === 0) throw new EmptyName()
  return `Hello, ${name}!`
}

import { EmptyName, greeting } from "./greeting.vibe"

service Greeter {
  greet(name: string): string!EmptyName
}

const GreeterLive = Layer.succeed(Greeter, {
  greet(name: string) { return greeting(name) }
})

export function main() {
  provide GreeterLive {
    Console.log(Greeter.greet("VibeLang"))
    try {
      Greeter.greet("")
    } catch (error) {
      Console.log(`Recovered from ${error._tag}`)
    }
  }
}

import { assert, it } from "@effect/vitest"
import { EmptyName, greeting } from "./greeting.vibe"

it.effect("greets a name") {
  assert.strictEqual(greeting("Ada"), "Hello, Ada!")
}

it.effect("recovers from an empty name") {
  try {
    greeting("")
    assert.fail("expected EmptyName")
  } catch (error) {
    assert.instanceOf(error, EmptyName)
  }
}

import { FileSystem } from "effect/FileSystem"
import { Path } from "effect/Path"
import { PlatformError } from "effect/PlatformError"
import { NodeServices } from "@effect/platform-node"

// collectFiles is recursive, so its contract is written out.
function collectFiles(directory: string, found: string[], visited: Set<string>): void!PlatformError!FileSystem | Path {
  const canonical = FileSystem.realPath(directory)
  if (visited.has(canonical)) return
  visited.add(canonical)
  const names = FileSystem.readDirectory(directory).sort()
  for (const name of names) {
    const path = Path.join(directory, name)
    const info = FileSystem.stat(path)
    if (info.type === "Directory") collectFiles(path, found, visited)
    else if (info.type === "File") found.push(path)
  }
}

function* walk(directory: string) {
  const files: string[] = []
  collectFiles(directory, files, new Set<string>())
  for (const path of files) yield path
}

function summarize(root: string) {
  const files: string[] = []
  for (const path of walk(root)) files.push(path)
  const lengths = forEach(files, (path) => {
    const text = FileSystem.readFileString(path)
    return { path: Path.relative(root, path), lines: text.trimEnd().split("\n").length }
  }, { concurrency: 4 })
  for (const file of lengths) Console.log(`${file.path}: ${file.lines} lines`)
}

export function main() {
  provide NodeServices.layer { summarize("fixtures") }
}

// await on a fiber and on a Deferred: EK4609 and EK4610, each with a quick fix (D226).
function count(): number!! {
  return 1
}

export function joinOld() {
  const f = fork count()
  return await f
}

export function waitOld() {
  const d = Deferred.make<number>()
  Deferred.succeed(d, 2)
  return await d
}

// A hatch's TypeScript reads a parameter: EK4405, and its quick fix passes it as an input.
export function measure(text: string) {
  return sync(() => text.length)
}

// A hatch with an input: hover on sync lists it.
export function count(text: string) {
  return sync((t) => t.length, text)
}

