package vibelangmapper

import (
	"github.com/microsoft/TypeScript/tsc/internal/ast"
)

// Forms (rule 3: form resolution, L1). A lambda, a block param, and an
// argument a callee takes by name each take the form the forms resolver
// decides from the file's syntax and the generated forms table
// (forms_resolve.go):
//
//	plain             (x) => body                  as written
//	Effect function   (x) => body                  (x) => $gen(function* () { return body })
//	program           () => body                   $gen(function* () { return body })
//	dual              () => body                   $dual($gen(function* () { return body }))
//
// The dual is a parameterless lambda that is both a program and a function
// that returns it; the prelude types it Effect<A, E, R> & (() => Effect<A, E, R>).
// Where the rules cannot decide (Decision.Choice), the projector reports
// EK9100 with the resolver's message and lowers the default's guess.

// isLambda reports whether node is a lambda the forms decide: an arrow
// function or a function expression written in the source, or a method of
// an object literal, with a body, neither async nor a generator.
func isLambda(node *ast.Node) bool {
	switch node.Kind {
	case ast.KindArrowFunction:
		arrow := node.AsArrowFunction()
		if arrow.EqualsGreaterThanToken == nil || arrow.EqualsGreaterThanToken.Flags&ast.NodeFlagsReparsed != 0 {
			return false
		}
	case ast.KindFunctionExpression:
		if node.AsFunctionExpression().AsteriskToken != nil {
			return false
		}
	case ast.KindMethodDeclaration:
		if node.Parent == nil || node.Parent.Kind != ast.KindObjectLiteralExpression || node.AsMethodDeclaration().AsteriskToken != nil {
			return false
		}
	default:
		return false
	}
	return node.Body() != nil && node.Flags&ast.NodeFlagsReparsed == 0 && !ast.HasSyntacticModifier(node, ast.ModifierFlagsAsync)
}

// lambda lowers fn, a lambda, to the form the resolver decides for it.
func (p *projector) lambda(fn *ast.Node, e env) {
	d := p.forms.Lambda(fn)
	form := d.Form
	if p.d4ServiceMember(fn) || p.providedMember(fn) && contractOf(fn.Type()) != contractPlain {
		// D173 gives the implementation the service member form, including pure methods.
		form = FormEffectFn
	} else {
		p.choice(d, fn)
	}

	if form == FormPlain && d.Call == nil && d.Provenance == FromFallback && fn.Type() == nil && p.keyLookupLambda(fn) {
		form = FormEffectFn
	}
	if form == FormProgram && len(fn.Parameters()) > 0 {
		// A program takes no arguments; one written with parameters is an
		// Effect function, which TypeScript then reports at the position.
		form = FormEffectFn
	}
	if fn.Kind == ast.KindMethodDeclaration && (form == FormProgram || form == FormDual) {
		form = FormEffectFn
	}
	if form == FormDual && d.Call == nil {
		// A dual no call takes is a function value, as the fork types it:
		// returned or bound, it reads as () => Effect<A, E, R>.
		form = FormEffectFn
	}
	switch form {
	case FormEffectFn:
		p.effectLambda(fn)
	case FormProgram, FormDual:
		p.programLambda(fn, form == FormDual)
	default:
		p.plainLambda(fn)
	}
}

// plainLambda unwraps a contract's success channel when the receiving
// position requires a plain callback (D9/D67). Keeping Effect here would
// promise a program even though the plain body returns its success value.
func (p *projector) plainLambda(fn *ast.Node) {
	ret := fn.Type()
	if ret == nil || !(isEffectType(ret) || isWrittenEffectReference(ret)) || len(ret.TypeArguments()) != 3 {
		p.visitChildren(fn, env{})
		return
	}
	success := ret.TypeArguments()[0]
	if success.Kind == ast.KindInferType {
		p.plan.replace(p.colonBefore(ret), ret.End(), "")
	} else {
		p.plan.replace(p.tokenStart(ret), p.tokenStart(success), "")
		p.visit(success, env{})
		p.plan.replace(success.End(), ret.End(), "")
	}
	fn.ForEachChild(func(child *ast.Node) bool {
		if child != ret {
			p.visit(child, env{})
		}
		return false
	})
}

// providedMember recognizes direct methods and function-valued properties of
// a D173 provider, without treating nested objects as service implementations.
func (p *projector) providedMember(fn *ast.Node) bool {
	member := fn
	if fn.Parent != nil && fn.Parent.Kind == ast.KindPropertyAssignment && fn.Parent.Initializer() == fn {
		member = fn.Parent
	}
	object := member.Parent
	return object != nil && object.Kind == ast.KindObjectLiteralExpression && object.Parent != nil && isProvideService(object.Parent) && object.Parent.Arguments()[2] == object
}

// choice reports EK9100 at d's node when the rules leave the form to the
// user (Decision.Choice), with the resolver's message.
func (p *projector) choice(d Decision, at *ast.Node) {
	if d.Choice == nil {
		return
	}
	if d.Node != nil {
		at = d.Node
	}
	start := p.tokenStart(at)
	p.diagnostics = append(p.diagnostics, Diagnostic{
		Start:   start,
		Length:  max(at.End()-start, 0),
		Code:    CodeFormChoice,
		Message: d.Choice.Message(),
	})
}

// effectLambda lowers fn in the Effect function form. A block body becomes
// its generator, as a function declaration's does; an expression body is
// the value the generator returns.
func (p *projector) effectLambda(fn *ast.Node) {
	body := fn.Body()
	if body.Kind == ast.KindBlock {
		p.functionLike(fn, body)
		return
	}
	p.callbackParameters(fn)
	// (x) => expr   (x) => $gen(function* () { return expr })
	fn.ForEachChild(func(child *ast.Node) bool {
		if child != body {
			p.visit(child, env{})
		}
		return false
	})
	if kind := contractOf(fn.Type()); kind == contractInfer {
		p.unprojected(fn.Type())
	}
	arg := "expr"
	if usesThis(body) {
		arg = "expr self"
	}
	start := p.tokenStart(body)
	p.plan.mark(editEffectBody, partOpen, start, start, arg)
	p.visit(body, expressionEnv())
	p.plan.mark(editEffectBody, partClose, body.End(), body.End(), arg)
}

// expressionEnv returns the env of a generator whose body is one
// expression, a lambda's: no block holds its code, so a fork there keeps
// Scope in R (D19).
func expressionEnv() env {
	e := newEffectEnv()
	e.frame.expression = true
	return e
}

// programLambda lowers fn, a lambda without parameters, in the program
// form: the lambda becomes its generator, an Effect value; with dual, an
// Effect value that is also a function returning it.
func (p *projector) programLambda(fn *ast.Node, dual bool) {
	body := fn.Body()
	start := p.tokenStart(fn)
	bodyStart := p.tokenStart(body)
	arg := ""
	if body.Kind != ast.KindBlock {
		arg = "expr"
	}
	if usesThis(body) {
		arg += " self"
	}
	if dual {
		p.plan.mark(editDual, partOpen, start, start, "")
	}
	p.plan.mark(editProgram, partOpen, start, bodyStart, arg)
	if body.Kind == ast.KindBlock {
		p.visitList(body.Statements(), newEffectEnv())
	} else {
		p.visit(body, expressionEnv())
	}
	p.plan.mark(editProgram, partClose, fn.End(), fn.End(), arg)
	if dual {
		p.plan.mark(editDual, partClose, fn.End(), fn.End(), "")
	}
}

// byNameArgument lowers argument, an argument of a call in any context,
// to a program when its callee takes it by name (D147): the expression runs
// when the callee runs the program, not where the call stands.
func (p *projector) byNameArgument(argument *ast.Node, e env) bool {
	if isLambda(argument) || formsIsTopic(argument) || argument.Flags&ast.NodeFlagsReparsed != 0 {
		return false
	}
	d := p.forms.Argument(argument)
	if !d.ByName {
		return p.programValue(argument, d, e)
	}
	arg := "expr"
	if usesThis(argument) {
		arg = "expr self"
	}
	start := p.tokenStart(argument)
	p.plan.mark(editProgram, partOpen, start, start, arg)
	p.visit(argument, expressionEnv())
	p.plan.mark(editProgram, partClose, argument.End(), argument.End(), arg)
	return true
}

// programValue lowers argument, a name or a member at a position that takes
// a program, to $asProgram(argument): a function value there runs as its
// program (D7), and any other value is itself.
func (p *projector) programValue(argument *ast.Node, d Decision, e env) bool {
	if d.Class&ClassProgram == 0 || d.Class&(ClassEffectFn|ClassPlainFn) != 0 {
		return false
	}
	switch argument.Kind {
	case ast.KindIdentifier, ast.KindPropertyAccessExpression:
	default:
		return false
	}
	start := p.tokenStart(argument)
	p.plan.mark(editProgramValue, partOpen, start, start, "")
	p.visit(argument, e)
	p.plan.mark(editProgramValue, partClose, argument.End(), argument.End(), "")
	return true
}

// blockArgument returns call's block param, the arrow the parser writes for
// `f(args) { block }` (D188), or nil.
func blockArgument(call *ast.Node) *ast.Node {
	arguments := call.Arguments()
	if len(arguments) == 0 {
		return nil
	}
	last := arguments[len(arguments)-1]
	if last.Kind != ast.KindArrowFunction || last.Body() == nil || last.Body().Kind != ast.KindBlock {
		return nil
	}
	arrow := last.AsArrowFunction().EqualsGreaterThanToken
	if arrow == nil || arrow.Flags&ast.NodeFlagsReparsed == 0 || len(last.Parameters()) != 0 {
		return nil
	}
	return last
}

// blockCall lowers call, `f(args) { block }`, with its block where the
// resolver places it (D188): appended, `f(args, block)`, or applied to the
// call, `f(args)(block)`, which is also where a data-first dual's block
// goes, since `f(block, args)` and `f(args)(block)` are one call of a dual.
// The block takes the form the resolver decides, a program when it moves.
func (p *projector) blockCall(call *ast.Node, block *ast.Node, e env) {
	d := p.forms.Block(call)
	p.choice(d, block)
	arguments := call.Arguments()
	written := arguments[:len(arguments)-1]
	body := block.Body()
	brace := p.tokenStart(body)
	closing := body.End() - 1
	if brace >= len(p.text) || p.text[brace] != '{' || p.text[closing] != '}' {
		p.unprojected(block)
		return
	}
	// The source's own ) before the block, or -1 for `f { block }`.
	paren := -1
	for i := brace - 1; i >= 0; i-- {
		if c := p.text[i]; c == ' ' || c == '\t' {
			continue
		} else if c == ')' {
			paren = i
		}
		break
	}
	for _, argument := range written {
		p.callArgument(argument, e)
	}
	var open string
	switch {
	case paren < 0:
		open = "("
	case d.Placement == BlockAppended && len(written) > 0:
		open = ", "
	case d.Placement == BlockAppended:
		open = ""
	default:
		open = ")("
	}
	from := brace
	if paren >= 0 {
		from = paren
	}
	p.plan.replace(from, brace, open)
	form := d.Form
	switch form {
	case FormEffectFn:
		p.plan.mark(editEffectBody, partOpen, brace, brace, "block "+selfArg(body))
		p.visitList(body.Statements(), newEffectEnv())
		p.plan.mark(editEffectBody, partClose, block.End(), block.End(), "block")
	case FormProgram, FormDual:
		if form == FormDual {
			p.plan.mark(editDual, partOpen, brace, brace, "")
		}
		p.plan.mark(editProgram, partOpen, brace, brace, selfArg(body))
		p.visitList(body.Statements(), newEffectEnv())
		p.plan.mark(editProgram, partClose, block.End(), block.End(), "")
		if form == FormDual {
			p.plan.mark(editDual, partClose, block.End(), block.End(), "")
		}
	default:
		p.plan.insert(brace, "() => ")
		p.visitList(body.Statements(), env{})
	}
	p.plan.insert(block.End(), ")")
}

// callArguments walks call's arguments: a block param where the resolver
// places it, and an argument its callee takes by name
// as a program. It reports whether it lowered a block param, which closes
// the call itself.
func (p *projector) callArguments(call *ast.Node, e env) bool {
	if block := blockArgument(call); block != nil {
		p.blockCall(call, block, e)
		return true
	}
	for _, argument := range call.Arguments() {
		p.callArgument(argument, e)
	}
	return false
}

// callArgument follows literal containers to the resolver's element and
// property paths. APIs such as Effect.all take programs inside a container;
// visiting only its outer array would run those programs before the API.
func (p *projector) callArgument(argument *ast.Node, e env) {
	if p.programPipeArgument(argument, e) || p.programCollection(argument, e) || p.byNameArgument(argument, e) {
		return
	}
	switch argument.Kind {
	case ast.KindParenthesizedExpression, ast.KindAsExpression, ast.KindSatisfiesExpression, ast.KindNonNullExpression:
		p.callArgument(argument.Expression(), e)
		if argument.Type() != nil {
			p.visit(argument.Type(), env{})
		}
	case ast.KindArrayLiteralExpression:
		for _, element := range argument.Elements() {
			p.callArgument(element, e)
		}
	case ast.KindObjectLiteralExpression:
		for _, property := range argument.Properties() {
			if property.Kind == ast.KindPropertyAssignment {
				p.visit(property.Name(), e)
				p.callArgument(property.Initializer(), e)
			} else if property.Kind == ast.KindShorthandPropertyAssignment && e.effect && p.forms.Argument(property.Name()).Class&ClassProgram != 0 {
				p.plan.insert(p.tokenStart(property), property.Name().Text()+": ")
				p.callArgument(property.Name(), e)
			} else {
				p.visit(property, e)
			}
		}
	default:
		p.visit(argument, e)
	}
}

// d4ServiceMember preserves D4's bare Effect type in a local service's
// written contract even when a value import also binds the name Effect.
// The forms resolver resolves that import as a namespace; projection of
// the declaration already treats its bare type spelling as the D4 alias.
func (p *projector) d4ServiceMember(fn *ast.Node) bool {
	if !p.names.shadowsPreludeType("Effect") {
		return false
	}
	member, object := fn, fn.Parent
	if object != nil && object.Kind == ast.KindPropertyAssignment && object.Initializer() == fn {
		member, object = object, object.Parent
	}
	if object == nil || object.Kind != ast.KindObjectLiteralExpression {
		return false
	}
	resolver, ok := p.forms.(*Resolver)
	if !ok {
		return false
	}
	key := resolver.providedKey(object)
	if key == nil || !ast.IsIdentifier(key) {
		return false
	}
	service := resolver.serviceClassOf(key)
	if service == nil || member.Name() == nil {
		return false
	}
	for _, declaration := range service.Members() {
		if declaration.Name() != nil && declaration.Name().Text() == member.Name().Text() && ast.IsMethodDeclaration(declaration) {
			ret := declaration.Type()
			return ret != nil && isWrittenEffectReference(ret) && ret.AsTypeReferenceNode().TypeName.Kind == ast.KindIdentifier
		}
	}
	return false
}

package vibelangmapper

import (
	"cmp"
	"slices"
	"strconv"
	"strings"

	"github.com/microsoft/TypeScript/tsc/internal/core"
	"github.com/microsoft/TypeScript/tsc/internal/spanmap"
)

// The lowering plan of one file is a list of edits to its text. The walk
// records each edit once, as what it means rather than as text; a rendering
// maps each edit to text. Two renderings share the plan:
//
//   - the checking rendering, the virtual TypeScript that stock tsc checks;
//   - the executable rendering, the code the compiler emits, which runs a
//     call by a run-time test where the checking rendering has $run's
//     types, splits a plain function into f$direct and an Effect wrapper
//     (D10), and never applies a checker-only witness, such as the second
//     call of a type guard in `((yield* $run(g(x))), g(x))`.
//
// This phase implements the checking rendering. The executable rendering
// is a placeholder that drops witnesses and implements no other kind; the
// plan carries no checking-only text it would have to undo.

// editKind is what an edit means. Kinds come in parts: an open and a close
// edit around source text, and sometimes a middle one.
type editKind uint8

const (
	// editSyntax rewrites syntax the same way in both renderings: a
	// keyword, punctuation, or a declaration's shape. Its text names
	// helpers as helperRef writes them.
	editSyntax editKind = iota
	// editWitness is checker-only text, which the executable rendering drops.
	editWitness
	// editRun runs a call where it stands (L3).
	editRun
	// editEffectBody makes a function's body an Effect: its generator. The
	// arg "self" passes this to the generator.
	editEffectBody
	// editContract checks a body against a contract with an infer channel (D57).
	editContract
	// editProgram makes a block a program: an Effect value whose generator
	// runs the block when the Effect runs (D7).
	editProgram
	// editFail fails with a thrown value (D46).
	editFail
	// editServiceCall reads a member call's receiver as a possible service key (D41).
	editServiceCall
	// editValueCall calls a value with no arguments, which runs an Effect value (D90).
	editValueCall
	// editBuiltinCall supplies the shipped failure contract of a caught built-in.
	editBuiltinCall
	// editPlainCall selects a D54 synchronous entry in a plain callback.
	editPlainCall
	// editRegion runs a block of an Effect function as an Effect of its own:
	// arg names the region's helper chain and completion variable.
	editRegion
	// editRecord is a completion record a region's block returns: a return,
	// break, or continue that leaves the region, or its normal end.
	editRecord
	// editDispatch acts on a region's completion record after it runs.
	editDispatch
	// editUsing acquires a using declaration's value in the block's Scope
	// (D47, D94): its initializer, passed by name.
	editUsing
	// editDual makes a parameterless lambda's program also a function that
	// returns it (L1's dual form).
	editDual
	// editScoped is a fork in a block, whose Scope owns the fiber (D19).
	editScoped
	// editProgramValue converts a function value at a program position to
	// its program (D7).
	editProgramValue
	// editProducer makes a generator function's body a producer, a Stream (D26).
	editProducer
	// editEmit is a producer's yield: it emits a value, or with arg
	// "delegate" every element of another producer.
	editEmit
	// editEach iterates a for...of's value: a Stream's elements, or an
	// iterable as itself (D26).
	editEach
	// editServiceBase is a service class's key (D45): fields are "service"
	// or "reference" (D40), the key, and the class's name.
	editServiceBase
	// editControl registers a control's operations (D2): fields are the
	// control's name, then each operation's name and arity, -1 for a rest
	// parameter. The checking rendering writes nothing.
	editControl
	// editScopeRegion is a block that holds a using or a fork, a region of
	// its own under $scopedBody (regions.go, scopeBlock), whose Scope ends
	// with the block (D14, D19). Both renderings write its text.
	editScopeRegion
	// editHatch carries the checking and executable spelling of a hatch boundary.
	editHatch
	// editDataMethod retains checking syntax and dispatches unproven receivers in execution.
	// A closing fragment's fields name the method whose candidates execution imports.
	editDataMethod
	// editRegionVar hoists storage, with a checker-only type witness.
	editRegionVar
)

// part says which part of a kind an edit is.
type part uint8

const (
	partOpen part = iota
	partMiddle
	partClose
	// partWhole is an edit of a kind that stands alone, such as a dispatch.
	partWhole
)

// edit replaces the original text in [pos, end) with what kind and part
// mean. An edit with pos == end inserts before the original character at pos.
type edit struct {
	pos  int
	end  int
	kind editKind
	part part
	// text is an editSyntax or editWitness edit's text, and the rendered
	// form of kinds whose text the walk computes (regions, records,
	// dispatches), in checking form.
	text string
	// arg is a kind-specific argument.
	arg string
	// pair identifies the edits of one construct: an open, its middles,
	// and its close share it, so a rendering never pairs them by order.
	// An edit that stands alone has 0.
	pair int
	// fields are a kind's structured data, for the renderings to write
	// from: a service base's key and name, a control's operations.
	fields []string
}

// helperRef writes a reference to a projection helper in edit text. Each
// rendering resolves it: the checking rendering to the prelude helper's
// local name.
func helperRef(name string) string { return "\x01" + name + "\x02" }

// plan is the lowering plan of one file.
type plan struct {
	edits []edit
	// open holds, per kind, the pair ids of the constructs opened and not
	// yet closed, innermost last. Each kind's edits nest in the order the
	// walk records them, so the stack pairs them.
	open  map[editKind][]int
	pairs int
}

// pairFor returns the pair id of a new edit of kind and part.
func (l *plan) pairFor(kind editKind, p part) int {
	if p == partWhole || kind == editSyntax || kind == editWitness {
		return 0
	}
	if l.open == nil {
		l.open = map[editKind][]int{}
	}
	stack := l.open[kind]
	switch p {
	case partOpen:
		l.pairs++
		l.open[kind] = append(stack, l.pairs)
		return l.pairs
	case partMiddle:
		if len(stack) == 0 {
			return 0
		}
		return stack[len(stack)-1]
	default:
		if len(stack) == 0 {
			return 0
		}
		l.open[kind] = stack[:len(stack)-1]
		return stack[len(stack)-1]
	}
}

// unclosed reports the kinds with a construct opened and never closed, a
// projector bug.
func (l *plan) unclosed() []editKind {
	var kinds []editKind
	for kind, stack := range l.open {
		if len(stack) > 0 {
			kinds = append(kinds, kind)
		}
	}
	return kinds
}

// insert records syntax text to insert before the original character at pos.
func (l *plan) insert(pos int, text string) {
	l.edits = append(l.edits, edit{pos: pos, end: pos, text: text})
}

// replace records syntax text to replace the original text in [pos, end).
func (l *plan) replace(pos int, end int, text string) {
	l.edits = append(l.edits, edit{pos: pos, end: end, text: text})
}

// witness records checker-only text to insert before the original
// character at pos.
func (l *plan) witness(pos int, text string) {
	l.edits = append(l.edits, edit{pos: pos, end: pos, kind: editWitness, text: text})
}

// mark records an edit of kind at [pos, end), with arg.
func (l *plan) mark(kind editKind, p part, pos int, end int, arg string) {
	l.edits = append(l.edits, edit{pos: pos, end: end, kind: kind, part: p, arg: arg, pair: l.pairFor(kind, p)})
}

// markText records an edit of kind at [pos, end) whose checking text the
// walk computed.
func (l *plan) markText(kind editKind, p part, pos int, end int, text string) {
	l.edits = append(l.edits, edit{pos: pos, end: end, kind: kind, part: p, text: text, pair: l.pairFor(kind, p)})
}

// reserve records an edit of kind at [pos, end) whose text the walk sets
// later, through the returned index: an edit that must apply before the
// edits a nested construct records at the same position.
func (l *plan) reserve(kind editKind, p part, pos int, end int) int {
	l.edits = append(l.edits, edit{pos: pos, end: end, kind: kind, part: p, pair: l.pairFor(kind, p)})
	return len(l.edits) - 1
}

// markFields records an edit of kind at [pos, end) with structured fields.
func (l *plan) markFields(kind editKind, p part, pos int, end int, fields ...string) {
	l.edits = append(l.edits, edit{pos: pos, end: end, kind: kind, part: p, fields: fields, pair: l.pairFor(kind, p)})
}

// rendering maps a plan's edits to text.
type rendering interface {
	// text returns the text of e, or ok false to leave e out.
	text(e edit) (text string, ok bool)
}

// checking is the checking rendering, the virtual TypeScript.
type checking struct {
	names *names
}

func (r checking) text(e edit) (string, bool) {
	var text string
	switch e.kind {
	case editSyntax, editWitness, editRegion, editDispatch:
		text = e.text
	case editRegionVar:
		text = e.fields[0]
	case editHatch, editDataMethod:
		text = e.text
	case editRecord:
		switch e.arg {
		case "return value":
			// return x in a region returns $box(x) (regions.go).
			text = pick(e.part, "return "+helperRef("$box")+"(", "", ")")
		case "return":
			// return without a value stays.
		default:
			text = e.text
		}
	case editRun:
		if strings.HasPrefix(e.arg, "channels ") {
			text = pick(e.part, "(yield* "+helperRef("$runAt")+"(", "", ", "+strings.TrimPrefix(e.arg, "channels ")+"))")
		} else {
			text = pick(e.part, "(yield* "+helperRef("$run")+"(", "", "))")
		}
	case editEffectBody:
		gen := helperRef("$gen") + "(function* () "
		if strings.Contains(e.arg, "self") {
			gen = helperRef("$gen") + "({ self: this }, function* () "
		}
		switch {
		case strings.HasPrefix(e.arg, "expr"):
			// (x) => expr
			text = pick(e.part, gen+"{ return ", "", " })")
		case strings.HasPrefix(e.arg, "block"):
			// a block param in the Effect function form
			text = pick(e.part, "() => "+gen, "", ")")
		default:
			// a function's braced body
			text = pick(e.part, " return "+gen+"{", "", "})")
		}
	case editContract:
		gen := helperRef("$gen") + "(function* () "
		if e.arg == "self" {
			gen = helperRef("$gen") + "({ self: this }, function* () "
		}
		text = pick(e.part, " { return "+helperRef("$contract")+"<", ">()("+gen, "))}")
	case editProgram:
		gen := helperRef("$gen") + "(function* () "
		if strings.Contains(e.arg, "self") {
			gen = helperRef("$gen") + "({ self: this }, function* () "
		}
		if strings.HasPrefix(e.arg, "expr") {
			text = pick(e.part, gen+"{ return ", "", " })")
		} else {
			text = pick(e.part, gen, "", ")")
		}
	case editDual:
		text = pick(e.part, helperRef("$dual")+"(", "", ")")
	case editScoped:
		// The checking-only scoped signature is selected on the callee.
		text = ""
	case editProgramValue:
		helper := "$asProgram"
		if e.arg == "collection" {
			helper = "$programs"
		}
		text = pick(e.part, helperRef(helper)+"(", "", ")")
	case editProducer:
		open := " return " + helperRef("$produce") + "(function* () {"
		if e.arg == "self" {
			open = " return " + helperRef("$produce") + "({ self: this }, function* () {"
		}
		text = pick(e.part, open, "", "})")
	case editEmit:
		switch e.arg {
		case "delegate":
			text = pick(e.part, helperRef("$delegate")+"(", "", ")")
		case "undefined":
			text = " " + helperRef("$emit") + "(undefined)"
		default:
			text = pick(e.part, helperRef("$emit")+"(", "", ")")
		}
	case editEach:
		text = pick(e.part, "(yield* "+helperRef("$each")+"(", "", "))")
	case editServiceBase:
		base, key, name := e.fields[0], e.fields[1], e.fields[2]
		text = helperRef("$"+base) + "<" + name + ">(" + strconv.Quote(key) + ")"
	case editScopeRegion:
		text = e.text
	case editControl:
		// Nothing to check: the registration only runs.
	case editFail:
		if e.arg == "void" {
			text = pick(e.part, "return (yield* "+helperRef("$fail")+"(", "", ")) as void")
		} else {
			text = pick(e.part, "return yield* "+helperRef("$fail")+"(", "", ")")
		}
	case editServiceCall:
		text = pick(e.part, helperRef("$use")+"(", "", ")")
	case editPlainCall:
		text = pick(e.part, helperRef("$plain")+"(", "", ")")
	case editBuiltinCall:
		text = renderBuiltinCall(e)
	case editValueCall:
		text = renderValueCall(e)
	case editUsing:
		text = pick(e.part, "(yield* "+helperRef("$acquire")+"(", "", "))")
	}
	return r.resolve(text), true
}

// resolve replaces each helper reference in text with the helper's local name.
func (r checking) resolve(text string) string {
	for {
		start := strings.IndexByte(text, '\x01')
		if start < 0 {
			return text
		}
		end := strings.IndexByte(text[start:], '\x02')
		if end < 0 {
			return text
		}
		end += start
		text = text[:start] + r.names.helper(text[start+1:end]) + text[end+1:]
	}
}

// String names k, as reports and the executable rendering's errors do.
func (k editKind) String() string {
	return [...]string{"syntax", "witness", "run", "effect body", "contract", "program", "fail", "service call",
		"value call", "region", "record", "dispatch", "using", "dual", "scoped", "program value", "producer", "emit", "each", "service base", "control", "scope region", "hatch", "data method", "region var"}[k]
}

// executable is the executable rendering, a placeholder: it leaves out
// checker-only witnesses and implements no other kind yet.
type executable struct{}

func (executable) text(e edit) (string, bool) {
	if e.kind == editWitness {
		return "", false
	}
	return renderExec(e)
}

// pick returns the text of part p among open, middle, and close.
func pick(p part, open, middle, close string) string {
	switch p {
	case partOpen:
		return open
	case partMiddle:
		return middle
	}
	return close
}

// render applies the plan's edits to original, after prefix, text that
// comes before every edit. Edits are sorted by position, stably, so edits
// at one position apply in the order the walk recorded them: an outer run
// opens before an inner one and closes after it. Each stretch of original
// text between edits is copied verbatim and gets a Verbatim segment with
// every language feature; rendered text is synthesized and gets none. ok
// is false when two edits overlap, a projector bug; the caller then passes
// the file through unchanged.
func (l *plan) render(r rendering, original string, prefix func() string) (text string, segments []spanmap.Segment, overlap int, ok bool) {
	edits := slices.Clone(l.edits)
	slices.SortStableFunc(edits, func(a, b edit) int { return cmp.Compare(a.pos, b.pos) })
	var body strings.Builder
	cursor := 0
	for _, e := range edits {
		if e.pos < cursor {
			return "", nil, e.pos, false
		}
		segments = appendVerbatim(segments, &body, original, cursor, e.pos)
		if t, keep := r.text(e); keep {
			body.WriteString(t)
		}
		cursor = e.end
	}
	segments = appendVerbatim(segments, &body, original, cursor, len(original))
	// The prefix is computed after the edits, because rendering them
	// records which helpers the prefix imports.
	head := prefix()
	for i := range segments {
		segments[i].VirtualStart += core.TextPos(len(head))
		segments[i].VirtualEnd += core.TextPos(len(head))
	}
	return head + body.String(), segments, 0, true
}

// appendVerbatim copies original[from:to] to out and appends its Verbatim
// segment, merged into the previous segment when the two are contiguous in
// both texts.
func appendVerbatim(segments []spanmap.Segment, out *strings.Builder, original string, from int, to int) []spanmap.Segment {
	if to <= from {
		return segments
	}
	virtualStart := core.TextPos(out.Len())
	out.WriteString(original[from:to])
	if n := len(segments); n > 0 && segments[n-1].VirtualEnd == virtualStart && segments[n-1].OriginalEnd == core.TextPos(from) {
		segments[n-1].VirtualEnd = core.TextPos(out.Len())
		segments[n-1].OriginalEnd = core.TextPos(to)
		return segments
	}
	return append(segments, spanmap.Segment{
		VirtualStart:  virtualStart,
		VirtualEnd:    core.TextPos(out.Len()),
		OriginalStart: core.TextPos(from),
		OriginalEnd:   core.TextPos(to),
		Kind:          spanmap.KindVerbatim,
		Features:      spanmap.FeatureAll,
	})
}

// compile checks one VibeLang source file with the pinned compiler and never runs it.
//
// Each call writes the source into a fresh temporary directory beside the fixed
// project's tsconfig, links the project's installed packages, and runs exactly
// `vibelang --noEmit --pretty false -p <dir>`: no user flags, no emit, and a
// minimal environment with no credentials. Limits: one CPU (GOMAXPROCS=1, plus
// the container's CPU quota), ten seconds of CPU and of wall time, a soft Go
// memory limit under the container's 512 MiB, and bounded output. The network
// is cut per compile with a user and network namespace (`unshare -rn`) where
// the host allows it; otherwise the deployment must deny egress, and the server
// refuses to start if it can reach the internet (see server.mjs).
import { spawn, spawnSync } from "node:child_process"
import { createHash } from "node:crypto"
import { existsSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const here = dirname(fileURLToPath(import.meta.url))

/** The largest source a conversion may compile, in bytes (the converter's own input limit). */
export const maxSourceBytes = 8 * 1024
const maxOutputBytes = 64 * 1024
const maxDiagnostics = 50
const maxMessageLength = 500

/**
 * Settings, from the environment so a deployment can pin them:
 *   VIBELANG_WORKER_PROJECT  the fixed project with installed packages (default ./project)
 *   VIBELANG_WORKER_BINARY   the native compiler (default: the platform package inside the project)
 *   VIBELANG_WORKER_TIMEOUT_MS  wall-clock limit (default 10000)
 *   VIBELANG_WORKER_NETWORK  "unshare" (cut the network per compile) or "policy" (the deployment denies egress)
 */
export function settings(env = process.env) {
  const project = env.VIBELANG_WORKER_PROJECT ?? join(here, "project")
  const binary = env.VIBELANG_WORKER_BINARY ?? platformBinary(project)
  const timeoutMs = Number(env.VIBELANG_WORKER_TIMEOUT_MS ?? 10_000)
  const network = env.VIBELANG_WORKER_NETWORK ?? "unshare"
  if (network !== "unshare" && network !== "policy") throw new Error(`VIBELANG_WORKER_NETWORK must be unshare or policy, not ${network}`)
  return { project, binary, timeoutMs, network }
}

function platformBinary(project) {
  const arch = process.arch === "arm64" ? "arm64" : "x64"
  return join(project, "node_modules", `vibelang-${process.platform}-${arch}`, "bin", process.platform === "win32" ? "vibelang.exe" : "vibelang")
}

const sha256 = (data) => createHash("sha256").update(data).digest("hex")

/** Names the compiler and the packages every receipt depends on. Computed once at startup. */
export function identity(config) {
  if (!existsSync(config.binary)) throw new Error(`no compiler at ${config.binary}`)
  const printed = spawnSync(config.binary, ["--version"], { encoding: "utf8", timeout: 10_000 })
  const match = /VibeLang (\S+)/.exec(printed.stdout ?? "")
  if (!match) throw new Error(`cannot read the compiler version: ${(printed.stdout ?? "") + (printed.stderr ?? "")}`)
  const versions = ["vibelang", "vibelang-runtime", "effect"].map((name) => {
    const manifest = join(config.project, "node_modules", name, "package.json")
    if (!existsSync(manifest)) throw new Error(`the fixed project is missing ${name}; install it first`)
    return `${name}@${JSON.parse(readFileSync(manifest, "utf8")).version}`
  })
  const lockfile = join(config.project, "package-lock.json")
  const locked = existsSync(lockfile) ? sha256(readFileSync(lockfile)) : "no-lockfile"
  return {
    vibelangVersion: match[1],
    compilerDigest: `sha256:${sha256(readFileSync(config.binary))}`,
    dependenciesDigest: `sha256:${sha256([...versions, `lock:${locked}`].join("\n"))}`,
    packages: versions
  }
}

/** Parses `--pretty false` diagnostics for the converted file into bounded records. */
export function parseDiagnostics(output) {
  const diagnostics = []
  for (const line of output.split("\n")) {
    const found = /(?:^|\/)main\.vibe\((\d+),(\d+)\): (error|warning) ([A-Z]+\d+): (.*)$/.exec(line)
    if (!found) continue
    diagnostics.push({
      line: Number(found[1]),
      column: Number(found[2]),
      severity: found[3],
      code: found[4],
      message: found[5].slice(0, maxMessageLength)
    })
    if (diagnostics.length === maxDiagnostics) break
  }
  return diagnostics
}

/**
 * Compiles one source. Resolves to `{ exitCode, timedOut, diagnostics, truncated }`; never throws for
 * a bad program, only for a worker fault (missing project or compiler).
 */
export function compile(source, config) {
  if (typeof source !== "string") throw new TypeError("source must be a string")
  if (Buffer.byteLength(source, "utf8") > maxSourceBytes) return Promise.resolve({ refusal: "too_large" })
  if (source.includes("\u0000")) return Promise.resolve({ refusal: "invalid_source" })
  const dir = mkdtempSync(join(tmpdir(), "vibelang-convert-"))
  writeFileSync(join(dir, "main.vibe"), source)
  writeFileSync(join(dir, "tsconfig.json"), readFileSync(join(here, "project", "tsconfig.json")))
  symlinkSync(join(config.project, "node_modules"), join(dir, "node_modules"))
  const argv = ["--noEmit", "--pretty", "false", "-p", dir]
  // prlimit: ten CPU-seconds and no core files; GOMAXPROCS=1: one CPU's worth of threads.
  const limited = ["prlimit", "--cpu=10", "--core=0", "--", config.binary, ...argv]
  const command = config.network === "unshare" ? ["unshare", "--net", "--map-root-user", "--", ...limited] : limited
  const env = { PATH: "/usr/bin:/bin", HOME: dir, TMPDIR: dir, GOMAXPROCS: "1", GOMEMLIMIT: "400MiB", LANG: "C.UTF-8" }
  return new Promise((resolve) => {
    const child = spawn(command[0], command.slice(1), { cwd: dir, env, stdio: ["ignore", "pipe", "pipe"] })
    let output = ""
    let truncated = false
    const take = (chunk) => {
      if (output.length >= maxOutputBytes) { truncated = true; return }
      output += chunk.toString("utf8").slice(0, maxOutputBytes - output.length)
    }
    child.stdout.on("data", take)
    child.stderr.on("data", take)
    let timedOut = false
    const timer = setTimeout(() => { timedOut = true; child.kill("SIGKILL") }, config.timeoutMs)
    child.on("close", (code, signal) => {
      clearTimeout(timer)
      rmSync(dir, { recursive: true, force: true })
      const diagnostics = parseDiagnostics(output)
      resolve({ exitCode: code ?? (signal ? 128 : 1), timedOut, diagnostics, truncated, ...(code !== 0 && diagnostics.length === 0 ? { workerOutput: output.slice(0, 2000) } : {}) })
    })
    child.on("error", (error) => {
      clearTimeout(timer)
      rmSync(dir, { recursive: true, force: true })
      resolve({ exitCode: 127, timedOut: false, diagnostics: [], truncated: false, workerOutput: String(error.message).slice(0, 500) })
    })
  })
}

/**
 * Proves the compile environment has no network: tries one outbound TCP connection inside the same
 * wrapper a compile uses. Resolves true when the connection fails, as it must.
 */
export function proveNoEgress(config, target = { host: "1.1.1.1", port: 443 }) {
  const probe = `const s=require("net").connect(${target.port},${JSON.stringify(target.host)});s.on("connect",()=>{console.log("EGRESS");process.exit(0)});s.on("error",()=>process.exit(3));setTimeout(()=>process.exit(4),3000)`
  const base = [process.execPath, "-e", probe]
  const command = config.network === "unshare" ? ["unshare", "--net", "--map-root-user", "--", ...base] : base
  const result = spawnSync(command[0], command.slice(1), { encoding: "utf8", timeout: 10_000 })
  // Only the probe's explicit connection-error or timeout exits prove a blocked connection.
  // Missing tools, namespace failures, signals, and spawn timeouts must fail closed.
  return !result.error && [3, 4].includes(result.status) && !(result.stdout ?? "").includes("EGRESS")
}

#!/usr/bin/env node
// Repack only vibelang's existing tarball when VIBELANG_SKIP leaves platforms out.
// No build or staging tree is used. All payloads except package.json must stay
// byte-identical, including the launcher and the packaged editor extension.
//
//   VIBELANG_SKIP=win32 node scripts/release/repack.mjs [tarball-directory]
import { deepStrictEqual } from "node:assert/strict"
import { execFileSync } from "node:child_process"
import { createHash } from "node:crypto"
import { lstatSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, readlinkSync, renameSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join, resolve } from "node:path"
import { fileURLToPath } from "node:url"

function payload(dir) {
  return readdirSync(dir, { recursive: true }).sort().flatMap((path) => {
    const file = join(dir, path)
    const stat = lstatSync(file)
    if (stat.isDirectory()) return []
    return [{ path, mode: stat.mode & 0o777, content: stat.isSymbolicLink() ? readlinkSync(file) : readFileSync(file) }]
  })
}

export function repack(tarballs, skip = process.env.VIBELANG_SKIP ?? "") {
  tarballs = resolve(tarballs)
  const manifestPath = join(tarballs, "manifest.json")
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8"))
  const entry = manifest.packages.find((pkg) => pkg.name === "vibelang")
  if (!entry) throw new Error("repack: manifest.json has no vibelang package")
  const tarball = join(tarballs, entry.file)
  const scratch = mkdtempSync(join(tmpdir(), "vibelang-repack-"))
  try {
    execFileSync("tar", ["-xzf", tarball, "-C", scratch])
    const dir = join(scratch, "package")
    const packagePath = join(dir, "package.json")
    const pkg = JSON.parse(readFileSync(packagePath, "utf8"))
    if (pkg.name !== "vibelang" || pkg.version !== manifest.version || pkg.version !== entry.version) {
      throw new Error(`repack: expected vibelang@${manifest.version}, got ${pkg.name}@${pkg.version}`)
    }
    const patterns = skip.split(/[,\s]+/).filter(Boolean)
    const removed = Object.keys(pkg.optionalDependencies ?? {}).filter((name) => patterns.some((pattern) => name.includes(pattern)))
    for (const name of removed) delete pkg.optionalDependencies[name]
    if (removed.length) {
      writeFileSync(packagePath, JSON.stringify(pkg, null, 2) + "\n")
      const expected = payload(dir)
      const packedDir = join(scratch, "packed")
      mkdirSync(packedDir)
      const [packed] = JSON.parse(execFileSync("npm", ["pack", dir, "--pack-destination", packedDir, "--ignore-scripts", "--json", "--silent"], { encoding: "utf8" }))
      if (packed.name !== pkg.name || packed.version !== pkg.version || packed.filename !== entry.file) {
        throw new Error("repack: npm pack changed the package identity")
      }
      const repacked = join(packedDir, packed.filename)
      const check = join(scratch, "check")
      mkdirSync(check)
      execFileSync("tar", ["-xzf", repacked, "-C", check])
      deepStrictEqual(payload(join(check, "package")), expected, "repack: npm pack changed package files or permissions")
      const sha256 = createHash("sha256").update(readFileSync(repacked)).digest("hex")
      Object.assign(entry, { size: packed.size, unpackedSize: packed.unpackedSize, files: packed.files.length, sha256 })
      // Move the verified tarball into place only after packing and validation.
      // Copy through the destination filesystem so TMPDIR can be another mount.
      const next = `${tarball}.repack`
      try {
        writeFileSync(next, readFileSync(repacked))
        renameSync(next, tarball)
      } finally {
        rmSync(next, { force: true })
      }
      writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n")
      console.log(`repack: removed ${removed.join(", ")} from vibelang@${pkg.version}`)
    }
    console.log(`repack: vibelang@${pkg.version} optionalDependencies: ${JSON.stringify(pkg.optionalDependencies ?? {})}`)
    console.log(`repack: ${entry.file} sha256 ${createHash("sha256").update(readFileSync(tarball)).digest("hex")}`)
  } finally {
    rmSync(scratch, { recursive: true, force: true })
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  repack(process.argv[2] ?? fileURLToPath(new URL("../../dist-npm/tarballs/", import.meta.url)))
}

