import { existsSync, readFileSync } from "node:fs"
import { resolve } from "node:path"
import { Marked, type Tokens } from "marked"
import type { ErrorNode, HoverNode, PageHovers } from "./hovers"

const escape = (text: string) => text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;")
const markdown = new Marked({ renderer: {
  html: ({ text }) => escape(text),
  // Documentation links often name declarations outside the published site.
  link(this: any, token: Tokens.Link) { return this.parser.parseInline(token.tokens) },
  image: ({ text }) => escape(text)
} })
const shortDocs = (docs: string) => {
  const summary = docs.trim().split(/\n\s*\n/).slice(0, 2).join("\n\n")
  const short = summary.length > 600 ? summary.slice(0, 599) + "…" : summary
  return short.split(/\n\s*\n/).filter(Boolean).map(p => `<span class="docs-docs">${markdown.parseInline(p)}</span>`).join("")
}
const hoverContent = (node: HoverNode) => escape(node.text) + (node.docs ? shortDocs(node.docs) : "")

// Both reading paths use exactly the ranges that can be shown in the source.
function hoverNodes(code: string, nodes: (HoverNode | ErrorNode)[]): HoverNode[] {
  let end = 0
  return nodes.filter((n): n is HoverNode => n.type === "hover" && Number.isInteger(n.start) && Number.isInteger(n.length) && n.start >= 0 && n.length > 0 && n.start + n.length <= code.length && code.slice(n.start, n.start + n.length) === n.target)
    .sort((a, b) => a.start - b.start || b.length - a.length)
    .filter(n => {
      if (n.start < end) return false
      end = n.start + n.length
      return true
    })
}

/** Offsets are UTF-16, as in the LSP cache. Invalid/stale ranges never eat code. */
export function renderHovers(code: string, nodes: (HoverNode | ErrorNode)[], highlight: (text: string) => string = escape): string {
  const valid = nodes.filter(n => Number.isInteger(n.start) && Number.isInteger(n.length) && n.start >= 0 && n.start <= code.length && n.length >= 0)
  const errors = valid.filter((n): n is ErrorNode => n.type === "error")
  const hovers = hoverNodes(code, nodes)
  const part = (start: number, end: number) => {
    const cuts = [...new Set([start, end, ...errors.flatMap(n => [n.start, n.start + n.length]).filter(p => p > start && p < end)])].sort((a, b) => a - b)
    return cuts.slice(0, -1).map((from, i) => {
      const to = cuts[i + 1]
      const active = errors.filter(n => n.start < to && n.start + n.length > from)
      const text = highlight(code.slice(from, to))
      return active.length ? `<span class="docs-error" title="${escape(active.map(n => `${n.code}: ${n.text}`).join("\n"))}">${text}</span>` : text
    }).join("")
  }
  let out = "", cursor = 0
  for (const node of hovers) {
    const end = node.start + node.length
    out += part(cursor, node.start)
    // The block's type list supplies the accessible text; pointer popups must
    // not interrupt the source when a screen reader reads the code.
    out += `<span class="docs-hover">${part(node.start, end)}<span class="docs-popup" aria-hidden="true">${hoverContent(node)}</span></span>`
    cursor = end
  }
  out += part(cursor, code.length)
  for (const node of errors.filter(n => n.start === code.length)) {
    out += `<span class="docs-error docs-error-end" title="${escape(`${node.code}: ${node.text}`)}" aria-label="${escape(`${node.code}: ${node.text}`)}"></span>`
  }
  return out
}

// Fixed positioning escapes pre's overflow-x scrollport. A viewport-sized panel
// also keeps long compiler signatures readable on narrow screens, in both themes.
export const hoverCss = process.env.VIBELANG_DOCS_HOVERS === "1" ? `
.docs-hover { cursor: help; text-decoration: underline dotted var(--muted); text-underline-offset: 3px; }
pre.code[tabindex]:focus-visible { outline: 2px solid var(--link); outline-offset: 2px; }
.docs-popup {
  display: none; position: fixed; z-index: 10; left: 50%; bottom: 16px; transform: translateX(-50%);
  width: max-content; max-width: min(60ch, calc(100vw - 32px)); max-height: 45vh; overflow: auto;
  padding: 12px 16px; border: 1px solid var(--rule); border-radius: 8px;
  background: var(--panel); color: var(--fg); box-shadow: 0 4px 20px color-mix(in srgb, var(--fg) 20%, transparent);
  text-decoration: none; cursor: auto;
}
.docs-hover:hover > .docs-popup { display: block; }
.docs-popup, .docs-types dd { font: 13px/1.5 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; white-space: pre-wrap; overflow-wrap: anywhere; }
.docs-docs { display: block; margin: 4px 0; font: 14px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif; white-space: normal; }
.docs-docs:first-of-type { margin-top: 8px; border-top: 1px solid var(--rule); padding-top: 8px; }
pre.code .docs-popup code { white-space: normal; font-size: 13px; }
.docs-types { display: none; margin-top: 8px; padding: 12px 16px; border: 1px solid var(--rule); border-radius: 8px; background: var(--panel); }
pre.code:focus-visible + .docs-types { display: block; }
.docs-types p { margin: 0 0 8px; font-weight: 600; }
.docs-types dl { margin: 0; }
.docs-types dt { margin-top: 12px; font-weight: 600; }
.docs-types dd { margin: 4px 0 0; }
.docs-error { text-decoration: underline wavy var(--accent); text-underline-offset: 3px; }
.docs-error-end { display: inline-block; width: .6ch; border-bottom: 2px solid var(--accent); }
` : ""

/** One opt-in renderer swap per page; an absent cache leaves Marked untouched. */
export function useHoverRenderer(marked: Marked, source: string, highlight: (text: string, lang: string) => string): void {
  if (process.env.VIBELANG_DOCS_HOVERS !== "1" || source.startsWith("spec/")) return
  const file = resolve(import.meta.dir, "../../.cache/docs-hovers", "src", source.replace(/\.md$/, ".json"))
  if (!existsSync(file)) return
  const page: PageHovers = JSON.parse(readFileSync(file, "utf8"))
  const blocks = new Map<string, typeof page.blocks>()
  const normalized = (code: string) => code.replace(/\n+$/, "")
  for (const block of page.blocks) {
    const key = normalized(block.code)
    blocks.set(key, [...blocks.get(key) ?? [], block])
  }
  const originalCode = marked.defaults.renderer!.code
  let example = 0
  marked.use({ renderer: { code(token: Tokens.Code) {
    const [lang, role] = (token.lang ?? "").split(/\s+/)
    if (!["vibe", "ts"].includes(lang) || role === "effect") return false
    const block = blocks.get(normalized(token.text))?.shift()
    if (!block?.nodes.length) return false
    // Keep captions and figures, including the comparison layout. One focus
    // stop reveals a type list after the scrollable pre. aria-describedby also
    // exposes its text to screen readers while CSS hides it from the pointer
    // view. No script, extra disclosure stop, or focusable identifier is needed.
    const renderer = marked.defaults.renderer!
    const original = originalCode.call(renderer, token) as string
    const rendered = original.replace(/<code>[\s\S]*<\/code>/, () => `<code>${renderHovers(token.text, block.nodes, text => highlight(text, lang))}</code>`)
    const hovers = hoverNodes(token.text, block.nodes)
    if (!hovers.length) return rendered
    const id = `docs-types-${++example}`
    // Repeated occurrences with identical popups need one entry. Different
    // types or docs for the same identifier stay distinct.
    const entries = [...new Set(hovers.map(node => `<dt><code>${escape(node.target)}</code></dt><dd>${hoverContent(node)}</dd>`))].join("")
    return rendered.replace(/<pre\b/, `<pre tabindex="0" role="group" aria-label="Code example with types" aria-describedby="${id}"`)
      .replace("</pre>", () => `</pre><div class="docs-types" id="${id}"><p>Types in this example</p><dl>${entries}</dl></div>`)
  } } })
}

// Run from the repository root: bun docs/tools/check-snippets.ts
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, realpathSync, rmSync, symlinkSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { dirname, join, relative, resolve } from "node:path"
import { createRequire } from "node:module"

const repo = resolve(import.meta.dir, "../..")
export type Diagnostic = { code: string; message: string; line?: number; column?: number }
export type Block = { number: number; line: number; language: "vibe" | "ts"; source: string; filename?: string; firstLine: string; expected: string[]; fragment: boolean; gap?: string }
export type Result = Block & { status: "ok" | "fragment" | "compiler-gap" | "fail"; diagnostics: Diagnostic[]; reason?: string }

export function extract(markdown: string): Block[] {
  const lines = markdown.split(/\r?\n/)
  const blocks: Block[] = []
  let number = 0
  for (let i = 0; i < lines.length; i++) {
    const fence = /^\s{0,3}(`{3,}|~{3,})([^`]*)$/.exec(lines[i])
    if (!fence) continue
    const start = i + 1
    const body: string[] = []
    const close = new RegExp(`^\\s{0,3}${fence[1][0]}{${fence[1].length},}\\s*$`)
    while (++i < lines.length && !close.test(lines[i])) body.push(lines[i])
    // The fence decides the language: ```vibe is VibeLang and ```ts is
    // TypeScript. ```ts effect marks Effect TypeScript shown for comparison,
    // which is not checked.
    const [lang, role] = fence[2].trim().split(/\s+/)
    if (lang !== "vibe" && lang !== "ts") continue
    if (lang === "ts" && role === "effect") continue
    const language = lang
    number++
    const filename = body.slice(0, 2).map(line => /^\s*\/\/\s+((?:[\w.-]+\/)*[\w.-]+\.(?:vibe|ts))\s*$/.exec(line)?.[1]).find(Boolean)
    if (filename?.split("/").some(part => part === "." || part === "..")) throw new Error(`Invalid snippet filename: ${filename}`)
    if (filename && !filename.endsWith(`.${language}`)) throw new Error(`${language === "ts" ? "A ts" : "A vibe"} fence names ${filename}; the fence decides the language`)
    // A TypeScript example without a filename, such as a framework's config, opts out.
    if (language === "ts" && /^\s*\/\/ TypeScript \(\.ts\)/.test(body[0] ?? "") && !filename) continue
    const headers: string[] = []
    for (const line of body) {
      if (!/^\s*\/\//.test(line)) break
      headers.push(line)
    }
    const header = headers.join("\n")
    blocks.push({ number, line: start + 1, language, source: body.join("\n"), filename,
      firstLine: body.find(l => l.trim() && !/^\s*\/\//.test(l)) ?? body[0] ?? "",
      expected: [...(header.match(/\/\/ expect-error:\s*([^\n]+)/)?.[1] ?? "").matchAll(/(?:EK|TS)\d+/g)].map(m => m[0]),
      fragment: /\/\/ fragment\s*(?:$|\n)/.test(header),
      gap: header.match(/\/\/ compiler-gap:\s*([^\n]+)/)?.[1] })
  }
  return blocks
}

// Repeated captions describe independent examples, so keep their numbered files.
// Unique captions are real source files, including TypeScript companion modules.
export function blockFilenames(blocks: Block[]): Map<number, string> {
  const counts = new Map<string, number>()
  for (const block of blocks) if (block.filename) counts.set(block.filename, (counts.get(block.filename) ?? 0) + 1)
  const used = new Set([...counts].filter(([, count]) => count === 1).map(([name]) => name))
  return new Map(blocks.map(block => {
    if (block.filename && counts.get(block.filename) === 1) return [block.number, block.filename]
    let filename = `block-${block.number}.${block.language}`
    for (let suffix = 2; used.has(filename); suffix++) filename = `block-${block.number}-${suffix}.${block.language}`
    used.add(filename)
    return [block.number, filename]
  }))
}

function localImport(from: string, to: string): string {
  const path = relative(dirname(from), to).replaceAll("\\", "/")
  return path.startsWith(".") ? path : "./" + path
}

function missing(d: Diagnostic) {
  return d.code === "TS2304" || d.code === "TS2552" ||
    (d.code === "TS2307" && /module ['"]\.{1,2}\//.test(d.message))
}

export function classify(block: Block, diagnostics: Diagnostic[]): Result {
  const codes = new Set(diagnostics.map(d => d.code))
  const absent = block.expected.filter(c => !codes.has(c))
  const unexpected = diagnostics.filter(d => !block.expected.includes(d.code))
  if (block.fragment) return { ...block, diagnostics, status: "fragment", reason: "Explicit fragment" }
  if (block.gap) {
    if (!absent.length && !unexpected.some(d => !missing(d))) return { ...block, diagnostics, status: "fail", reason: "Stale compiler-gap marker; remove it" }
    return { ...block, diagnostics, status: "compiler-gap", reason: absent.length ? `${block.gap}; missing ${absent.join(", ")}` : block.gap }
  }
  if (absent.length) return { ...block, diagnostics, status: "fail", reason: `Expected ${absent.join(", ")} was not reported` }
  return { ...block, diagnostics, status: unexpected.length === 0 ? "ok" : unexpected.every(missing) ? "fragment" : "fail" }
}

export function parseDiagnostics(output: string): { file?: string; diagnostic: Diagnostic }[] {
  const result: { file?: string; diagnostic: Diagnostic }[] = []
  for (const line of output.split(/\r?\n/)) {
    const m = /^(.*)\((\d+),(\d+)\): error ((?:TS|EK)\d+): (.*)$/.exec(line)
    if (m) result.push({ file: m[1], diagnostic: { code: m[4], message: m[5], line: +m[2], column: +m[3] } })
    else {
      const global = /^error ((?:TS|EK)\d+): (.*)$/.exec(line)
      if (global) result.push({ diagnostic: { code: global[1], message: global[2] } })
    }
  }
  return result
}

// The Markdown pages under root, except root/site: render-user.ts builds the
// site there, with a Markdown copy of every page and specification chapter.
export function markdownPages(root: string): string[] {
  const walk = (path: string): string[] => readdirSync(path, { withFileTypes: true }).flatMap(e =>
    e.isDirectory() ? (join(path, e.name) === join(root, "site") ? [] : walk(join(path, e.name))) : e.name.endsWith(".md") ? [join(path, e.name)] : [])
  return walk(root).sort()
}

// The compiler that VIBELANG_BINARY names, else the local build, else vibelang on PATH.
export function defaultCompiler(): string {
  const local = join(repo, "typescript/built/local/tsc")
  return process.env.VIBELANG_BINARY || (existsSync(local) ? local : "vibelang")
}

// The experiments package pins this parser. It only discovers declarations;
// all language checking belongs to the native VibeLang compiler.
let parser: typeof import("../../experiments/node_modules/typescript") | undefined
const typescript = () => parser ??= createRequire(join(repo, "experiments/package.json"))("typescript") as NonNullable<typeof parser>

// The vibelang-runtime that page projects import. VIBELANG_RUNTIME_DIR checks
// against another one, such as a release tarball's package.
export function runtimeDir(): string {
  return process.env.VIBELANG_RUNTIME_DIR || join(repo, "packages/runtime")
}

// Links the packages that every page project imports into temp/node_modules.
export function linkModules(temp: string) {
  const modules = join(temp, "node_modules")
  mkdirSync(modules, { recursive: true })
  // vibelang-runtime is a symlink to packages/runtime, which resolves effect
  // from its own node_modules. Give the project that same copy: TypeScript
  // merges two copies of a package only for files an import loads, so with
  // two copies a module augmentation such as `declare module "effect/Schema"`
  // can name the copy outside the program and fail with TS2664, depending on
  // which copy the parallel file loader reaches first.
  // A runtime without its own node_modules, such as a release tarball's
  // package, shares the repo's effect.
  const runtime = runtimeDir()
  const ownEffect = join(runtime, "node_modules/effect")
  const runtimeEffect = existsSync(join(ownEffect, "package.json")) ? ownEffect : join(repo, "packages/runtime/node_modules/effect")
  if (existsSync(join(runtimeEffect, "package.json"))) symlinkSync(realpathSync(runtimeEffect), join(modules, "effect"))
  const dependencies = [join(repo, "experiments/node_modules"), join(repo, "docs/tools/node_modules")]
  for (const source of dependencies) {
    if (!existsSync(source)) continue
    for (const name of readdirSync(source).filter(n => !n.startsWith("."))) {
      if (name === "vibelang-runtime" || name === "vibelang-vite") continue
      const target = join(modules, name)
      if (!existsSync(target)) symlinkSync(join(source, name), target)
    }
  }
  symlinkSync(runtime, join(modules, "vibelang-runtime"))
  symlinkSync(join(repo, "packages/vite"), join(modules, "vibelang-vite"))
  if (!existsSync(join(modules, "effect/package.json")) || !existsSync(join(runtime, "dist/index.d.ts"))) {
    throw new Error("Install experiments dependencies and build packages/runtime before checking snippets (see docs/tools/README.md)")
  }
}

// Writes one page's blocks to dir, inside a directory that linkModules
// prepared, as a project: one module per block, whose prefix imports the
// names that earlier blocks declare, and a tsconfig.json that lists them.
// offsets holds the number of prefix lines in each module.
export function writeProject(dir: string, blocks: Block[]): { filenames: Map<number, string>; offsets: Map<string, number> } {
  const ts = typescript()
  mkdirSync(dir)
  writeFileSync(join(dir, "package.json"), '{"type":"module","name":"docs-snippets"}')
  const filenames = blockFilenames(blocks)
  const scope = new Map<string, { from: string; value: boolean }>()
  const offsets = new Map<string, number>()
  for (const block of blocks) {
    const filename = filenames.get(block.number)!
    mkdirSync(dirname(join(dir, filename)), { recursive: true })
    if (filename.endsWith(".ts")) {
      offsets.set(filename, 0)
      writeFileSync(join(dir, filename), block.source + "\n")
      continue
    }
    const ast = ts.createSourceFile(filename, block.source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
    const names = new Set<string>()
    const exported = new Set<string>()
    const typeOnly = new Set<string>()
    const localValues = new Set<string>()
    const bindings = (node: any) => {
      // Recovery from VibeLang forms, such as a block param, can yield a nameless declaration.
      if (ts.isIdentifier(node)) { if (node.text) names.add(node.text) }
      else if (ts.isObjectBindingPattern(node) || ts.isArrayBindingPattern(node)) {
        for (const e of node.elements) if (ts.isBindingElement(e)) bindings(e.name)
      }
    }
    for (const statement of ast.statements) {
      // TypeScript's parser cannot read VibeLang's statement forms, such as
      // `fork { ... }` and `select { ... }`, and its recovery can lift
      // statements out of a function. Top-level code starts in column 0.
      if (ast.getLineAndCharacterOfPosition(statement.getStart(ast)).character !== 0) continue
      const before = new Set(names)
      if (ts.isImportDeclaration(statement)) {
        const clause = statement.importClause
        if (clause?.name) bindings(clause.name)
        const named = clause?.namedBindings
        if (named && ts.isNamespaceImport(named)) bindings(named.name)
        else if (named) for (const element of named.elements) bindings(element.name)
      } else if (ts.isVariableStatement(statement)) {
        // Recovery from a block param, `const x = f(a) { ... }`, reads the
        // block as another declaration; real ones follow a comma.
        const declarations = statement.declarationList.declarations
        for (const [i, d] of declarations.entries()) {
          if (i > 0 && !block.source.slice(declarations[i - 1].end, d.getStart(ast)).includes(",")) continue
          bindings(d.name)
          if (ts.isIdentifier(d.name)) localValues.add(d.name.text)
        }
      } else if ("name" in statement && statement.name && ts.isIdentifier(statement.name)) bindings(statement.name)
      if (ts.isTypeAliasDeclaration(statement) || ts.isInterfaceDeclaration(statement)) typeOnly.add(statement.name.text)
      else for (const name of names) if (!before.has(name)) localValues.add(name)
      if (ts.canHaveModifiers(statement) && ts.getModifiers(statement)?.some(m => m.kind === ts.SyntaxKind.ExportKeyword) && !ts.getModifiers(statement)?.some(m => m.kind === ts.SyntaxKind.DefaultKeyword)) {
        for (const name of names) if (!before.has(name)) exported.add(name)
      }
    }
    // TypeScript's parser reads VibeLang's declaration forms, such as
    // `error NotFound { id: string }`, as expression statements, so their
    // names come from the source text. Each declares a value. `service`
    // and `control` may be followed by `class`, the older spelling (D223).
    for (const m of block.source.matchAll(/^(export\s+)?(?:error|(?:service|control)(?:\s+class)?|layer|schema)\s+([A-Za-z_$][\w$]*)/gm)) {
      names.add(m[2])
      localValues.add(m[2])
      if (m[1]) exported.add(m[2])
    }
    for (const name of localValues) typeOnly.delete(name)
    const imports = new Map<string, string[]>()
    const values: string[] = []
    for (const [name, previous] of scope) {
      if (names.has(name) && !(typeOnly.has(name) && previous.value)) continue
      const list = imports.get(previous.from) ?? []
      if (typeOnly.has(name)) {
        list.push(`${name} as $doc_${name}`)
        values.push(`const ${name} = $doc_${name}`)
      } else list.push(name)
      imports.set(previous.from, list)
    }
    const prefix = [...[...imports].map(([from, ids]) => `import { ${ids.join(", ")} } from "${localImport(filename, from)}"`), ...values].join("\n") + "\n"
    offsets.set(filename, prefix.split("\n").length - 1)
    writeFileSync(join(dir, filename), `${prefix}${block.source}\nexport { ${[...names].filter(n => !exported.has(n)).join(", ")} }\n`)
    // An example that deliberately fails or opts out cannot supply reliable
    // definitions to later examples. Other blocks share their latest names.
    if (!block.fragment && !block.expected.length) for (const name of names) scope.set(name, { from: filename, value: !typeOnly.has(name) || values.some(v => v.startsWith(`const ${name} =`)) })
  }
  writeFileSync(join(dir, "tsconfig.json"), JSON.stringify({ compilerOptions: {
    strict: true, target: "ESNext", module: "NodeNext", moduleResolution: "NodeNext",
    skipLibCheck: true, noEmit: true, types: [], rewriteRelativeImportExtensions: true
  }, files: [...filenames.values()] }))
  return { filenames, offsets }
}

async function main() {
  const args = process.argv.slice(2)
  function option(name: string, fallback?: string) {
    const i = args.indexOf(name)
    if (i < 0) return fallback
    if (!args[i + 1] || args[i + 1].startsWith("--")) throw new Error(`${name} requires a value`)
    const value = args[i + 1]
    args.splice(i, 2)
    return value
  }
  if (args.includes("--help")) {
    console.log("bun docs/tools/check-snippets.ts [--compiler path] [--root docs/user] [--filter text] [--json path] [--keep]")
    return
  }
  const selectedCompiler = option("--compiler", defaultCompiler())!
  const compiler = selectedCompiler.includes("/") ? resolve(selectedCompiler) : selectedCompiler
  const root = resolve(option("--root", join(repo, "docs/user"))!)
  const filter = option("--filter", "")!
  const json = option("--json")
  const keep = args.includes("--keep")
  if (args.some(a => a !== "--keep")) throw new Error(`Unknown argument: ${args.join(" ")}`)
  const temp = mkdtempSync(join(tmpdir(), "vibelang-docs-"))
  const pages: { page: string; blocks: Result[] }[] = []
  try {
    linkModules(temp)
    let index = 0
    for (const page of markdownPages(root).filter(p => relative(root, p).includes(filter))) {
      const blocks = extract(readFileSync(page, "utf8"))
      if (!blocks.length) continue
      const dir = join(temp, String(++index))
      const { filenames, offsets } = writeProject(dir, blocks)
      const child = Bun.spawn([compiler, "--noEmit", "--pretty", "false", "-p", join(dir, "tsconfig.json")], { cwd: dir, stdout: "pipe", stderr: "pipe" })
      const [stdout, stderr, code] = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited])
      const output = `${stdout}\n${stderr}`
      if (keep) writeFileSync(join(dir, "compiler.log"), output)
      const parsed = parseDiagnostics(output)
      const infrastructure = parsed.filter(d => !d.file || !offsets.has(relative(dir, resolve(dir, d.file)).replaceAll("\\", "/")))
      if (infrastructure.length || (code !== 0 && !parsed.length)) throw new Error(`Compiler failed for ${relative(repo, page)} (exit ${code}):\n${output}`)
      const results = blocks.map(block => {
        const filename = filenames.get(block.number)!
        const diagnostics = parsed.filter(d => d.file && relative(dir, resolve(dir, d.file)).replaceAll("\\", "/") === filename).map(({ diagnostic }) => ({
          ...diagnostic, line: block.line + diagnostic.line! - offsets.get(filename)! - 1
        }))
        return classify(block, diagnostics)
      })
      pages.push({ page: relative(repo, page), blocks: results })
      console.log(`\n${relative(repo, page)}\n| Block | Line | Status | Diagnostics |\n| --- | --- | --- | --- |`)
      for (const result of results) {
        console.log(`| ${result.number} | ${result.line} | ${result.status} | ${[...new Set(result.diagnostics.map(d => d.code))].join(", ") || "-"} |`)
        if (result.status === "fail") {
          if (result.reason) console.log(`  ${result.reason}`)
          for (const d of result.diagnostics) console.log(`  ${d.line}:${d.column} ${d.code}: ${d.message}`)
        }
      }
    }
    const totals = { pages: pages.length, blocks: 0, ok: 0, fragment: 0, "compiler-gap": 0, fail: 0 }
    for (const page of pages) for (const block of page.blocks) { totals.blocks++; totals[block.status]++ }
    console.log(`\nTotals: ${JSON.stringify(totals)}`)
    if (json) writeFileSync(resolve(json), JSON.stringify({ compiler, totals, pages }, null, 2) + "\n")
    if (totals.fail) process.exitCode = 1
  } finally {
    if (keep) console.log(`Temporary projects: ${temp}`)
    else rmSync(temp, { recursive: true, force: true })
  }
}

if (import.meta.main) main().catch(error => { console.error(error.message); process.exitCode = 2 })

package astnav

import (
	"github.com/microsoft/TypeScript/tsc/internal/ast"
	"github.com/microsoft/TypeScript/tsc/internal/scanner"
	"github.com/microsoft/TypeScript/tsc/internal/tspath"
)

// VibeLang (.vibe) forms parse into the TypeScript nodes they abbreviate
// (parser/vibelang.go), and the nodes a form synthesizes carry
// NodeFlagsReparsed, so this package's walk skips them. Two things then leave
// a source token where getTokenAtPosition expects only trivia between a node's
// children:
//
//   - The word that names a form, such as error, match, when, join, or the all
//     of await.all, is an identifier with no node of its own.
//   - A desugared node can hold source children out of source order, or
//     outside its own range, so a binary search by position misses them:
//     for concurrent(8) (const id of ids) passes ids before 8, and its body
//     function starts after the binding id.
//
// TypeScript code has neither, so outside .vibe files an identifier in
// trivia still panics, as upstream.

func isVibeLangSourceFile(sourceFile *ast.SourceFile) bool {
	return tspath.FileExtensionIs(string(sourceFile.FileName()), tspath.ExtensionVibe)
}

// vibelangSourceToken returns the source node that is exactly the token at
// [start, end), found below current or else below its nearest ancestor that
// holds it, or nil. A desugared node can range over a sibling's source child,
// as the body function of for concurrent ranges over its items, so the walk
// can stop below the node that holds the token. It visits every child in
// order rather than searching by position, and never descends into a
// synthesized node, so the node it returns has only source nodes above it.
func vibelangSourceToken(sourceFile *ast.SourceFile, current *ast.Node, start int, end int) *ast.Node {
	var found *ast.Node
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Flags&ast.NodeFlagsReparsed != 0 || node.End() < end ||
			scanner.GetTokenPosOfNode(node, sourceFile, false /*includeJSDoc*/) > start {
			return false
		}
		if node.End() == end && scanner.GetTokenPosOfNode(node, sourceFile, false /*includeJSDoc*/) == start && ast.IsTokenKind(node.Kind) {
			found = node
			return true
		}
		return node.ForEachChild(visit)
	}
	for scope := current; scope != nil && found == nil; scope = scope.Parent {
		scope.ForEachChild(visit)
	}
	return found
}

// vibelangWordNode returns the node that stands for the word of a VibeLang form
// at the scanner's current token, where no source node covers it. The word
// of a declaration that parses into a class, error, service, control, or the
// older layer, is that class's class keyword, and the word of one that parses
// into a const, schema or layer, is its const keyword, so the language
// service treats each as TypeScript treats those keywords: rename and go to
// definition move to the declared name. Any other word stands for the form
// itself, the node that contains it, which hovers describe.
func vibelangWordNode(sourceFile *ast.SourceFile, current *ast.Node, s *scanner.Scanner, fullStart int, end int, flags ast.TokenFlags) *ast.Node {
	switch s.TokenValue() {
	case "error", "service", "control", "layer", "schema":
		if ast.IsClassDeclaration(current) {
			return sourceFile.GetOrCreateToken(ast.KindClassKeyword, fullStart, end, current, flags)
		}
		if ast.IsVariableStatement(current) {
			if list := current.AsVariableStatement().DeclarationList; list != nil && list.Flags&ast.NodeFlagsReparsed == 0 {
				return sourceFile.GetOrCreateToken(ast.KindConstKeyword, fullStart, end, list, flags)
			}
		}
	}
	return current
}

